class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def digit_sum(x):
            return sum(int(digit) for digit in str(x))

        def is_bad_integer(num_str, min_val, max_val):
            val = int(num_str)
            return min_val <= digit_sum(val) <= max_val

        num1_digits = len(num1)
        num2_digits = len(num2)

        start = int(num1)
        end = int(num2)

        if is_bad_integer(str(start), min_sum, max_sum):
            bad_count = 1
        else:
            bad_count = 0

        if num1 == num2:
            return bad_count

        for i in range(1, 10):
            if num1_digits < num2_digits:
                if is_bad_integer(str(start) + str(i), min_sum, max_sum):
                    bad_count += 1
            else:
                if is_bad_integer(str(i) + str(end), min_sum, max_sum):
                    bad_count += 1

        return bad_count % MOD
